query:
UPDATE site_settings 
SET value = CONCAT('https://media.yukvix.com/', SUBSTRING_INDEX(SUBSTRING(value, LOCATE('/cms/', value) + 1), '?', 1))
WHERE `key` = 'logo_url' AND value LIKE 'https://s3.ap-southeast-1.wasabisys.com/%';

